-- Portable SQLite / Cloudflare D1 starter. Illustrative migration only.
-- Do not execute against MTSS without schema review and a migration plan.
PRAGMA foreign_keys = ON;
CREATE TABLE fluency_tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE fluency_schools (tenant_id TEXT NOT NULL REFERENCES fluency_tenants(id), id TEXT NOT NULL, name TEXT NOT NULL, PRIMARY KEY(tenant_id,id));
CREATE TABLE fluency_classes (tenant_id TEXT NOT NULL, id TEXT NOT NULL, school_id TEXT NOT NULL, grade INTEGER NOT NULL CHECK(grade BETWEEN 1 AND 12), name TEXT NOT NULL, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,school_id) REFERENCES fluency_schools(tenant_id,id));
-- student_id is the host's opaque roster ID. Resolve display names through authorized MTSS roster services.
CREATE TABLE fluency_enrollments (tenant_id TEXT NOT NULL, student_id TEXT NOT NULL, class_id TEXT NOT NULL, PRIMARY KEY(tenant_id,student_id), FOREIGN KEY(tenant_id,class_id) REFERENCES fluency_classes(tenant_id,id));
CREATE TABLE fluency_facts (id TEXT PRIMARY KEY, operation TEXT NOT NULL CHECK(operation IN ('add','sub','mul','div')), a INTEGER NOT NULL, b INTEGER NOT NULL, answer INTEGER NOT NULL);
CREATE TABLE fluency_fact_state (tenant_id TEXT NOT NULL, student_id TEXT NOT NULL, fact_id TEXT NOT NULL REFERENCES fluency_facts(id), stage INTEGER NOT NULL CHECK(stage BETWEEN 0 AND 4), refresh INTEGER NOT NULL DEFAULT 0 CHECK(refresh BETWEEN 0 AND 2), due_date TEXT, last_success TEXT, rules_version TEXT NOT NULL, PRIMARY KEY(tenant_id,student_id,fact_id), FOREIGN KEY(tenant_id,student_id) REFERENCES fluency_enrollments(tenant_id,student_id));
CREATE TABLE fluency_responses (tenant_id TEXT NOT NULL, event_id TEXT NOT NULL, student_id TEXT NOT NULL, fact_id TEXT NOT NULL REFERENCES fluency_facts(id), occurred_at TEXT NOT NULL, school_day TEXT NOT NULL, game TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('correct','incorrect','timeout')), elapsed_ms INTEGER NOT NULL CHECK(elapsed_ms BETWEEN 0 AND 3000), assisted INTEGER NOT NULL DEFAULT 0 CHECK(assisted IN(0,1)), demo INTEGER NOT NULL DEFAULT 0 CHECK(demo IN(0,1)), rules_version TEXT NOT NULL, PRIMARY KEY(tenant_id,event_id), FOREIGN KEY(tenant_id,student_id) REFERENCES fluency_enrollments(tenant_id,student_id));
CREATE TABLE fluency_sessions (tenant_id TEXT NOT NULL, id TEXT NOT NULL, student_id TEXT NOT NULL, school_day TEXT NOT NULL, game TEXT NOT NULL, practice_ms INTEGER NOT NULL CHECK(practice_ms>=0), demo INTEGER NOT NULL CHECK(demo IN(0,1)), PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES fluency_enrollments(tenant_id,student_id));
CREATE TABLE fluency_checks (tenant_id TEXT NOT NULL, id TEXT NOT NULL, student_id TEXT NOT NULL, school_day TEXT NOT NULL, pathway TEXT NOT NULL CHECK(pathway IN('add','sub','mul','div','mixed')), correct INTEGER NOT NULL CHECK(correct>=0), incorrect INTEGER NOT NULL CHECK(incorrect>=0), timeouts INTEGER NOT NULL CHECK(timeouts>=0), attempted INTEGER NOT NULL CHECK(attempted>0 AND attempted=correct+incorrect+timeouts), duration_seconds INTEGER NOT NULL CHECK(duration_seconds=90), official INTEGER NOT NULL CHECK(official IN(0,1)), valid INTEGER NOT NULL CHECK(valid IN(0,1)), rules_version TEXT NOT NULL, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES fluency_enrollments(tenant_id,student_id));
CREATE UNIQUE INDEX fluency_official_day ON fluency_checks(tenant_id,student_id,pathway,school_day) WHERE official=1 AND valid=1;
CREATE TABLE fluency_snapshots (tenant_id TEXT NOT NULL, student_id TEXT NOT NULL, pathway TEXT NOT NULL CHECK(pathway IN('add','sub','mul','div','mixed')), school_day TEXT NOT NULL, full_set_confirmed INTEGER NOT NULL CHECK(full_set_confirmed IN(0,1)), rules_version TEXT NOT NULL, PRIMARY KEY(tenant_id,student_id,pathway,school_day), FOREIGN KEY(tenant_id,student_id) REFERENCES fluency_enrollments(tenant_id,student_id));
CREATE INDEX fluency_review_due ON fluency_fact_state(tenant_id,due_date,student_id);
CREATE INDEX fluency_response_history ON fluency_responses(tenant_id,student_id,fact_id,occurred_at);
CREATE INDEX fluency_check_window ON fluency_checks(tenant_id,pathway,school_day);
